<script setup>
import { onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { adminApi } from '../../api/services.js'
import { useSeo } from '../../composables/useSeo.js'
import { formatDateTime,formatMoney,orderSourceLabel,orderStatusLabel,paymentStatusLabel } from '../../utils/format.js'
const route=useRoute(),loading=ref(false),result=ref({items:[],total:0,page:1,size:25});const filters=reactive({page:1,size:25,search:'',status:String(route.query.status||''),payment_status:String(route.query.payment_status||''),source:''});let timer
useSeo({title:'Order | Velmora Admin',description:'Manage orders.',path:'/admin/orders',noindex:true})
async function load(){loading.value=true;try{result.value=await adminApi.orders({page:filters.page,size:filters.size,search:filters.search||undefined,status:filters.status||undefined,payment_status:filters.payment_status||undefined,source:filters.source||undefined})}finally{loading.value=false}}
onMounted(load);watch(()=>[filters.status,filters.payment_status,filters.source,filters.page],load);watch(()=>filters.search,()=>{clearTimeout(timer);timer=setTimeout(()=>{filters.page=1;load()},300)});const pages=()=>Math.max(1,Math.ceil(result.value.total/result.value.size))
</script>
<template><section class="admin-page"><div class="admin-page-head"><div><p>ORDER</p><h1 class="ui-display">Order</h1><span>Website, phone, messengers and manual orders in one list.</span></div><RouterLink class="btn btn-primary admin-create" to="/admin/orders/new">+ New order</RouterLink></div><div class="admin-toolbar"><a href="/api/v1/admin/orders/export.csv" download>Export orders (CSV)</a></div><div class="admin-toolbar"><input v-model="filters.search" class="admin-search" type="search" placeholder="Number, customer, phone, email or tracking"><select v-model="filters.status" class="admin-select"><option value="">All statuses</option><option v-for="s in ['new','confirmed','processing','shipped','completed','cancelled','returned']" :key="s" :value="s">{{orderStatusLabel(s)}}</option></select><select v-model="filters.payment_status" class="admin-select"><option value="">All payment statuses</option><option v-for="s in ['unpaid','pending','paid','refunded']" :key="s" :value="s">{{paymentStatusLabel(s)}}</option></select><select v-model="filters.source" class="admin-select"><option value="">All sources</option><option v-for="s in ['website','manual','phone','telegram','viber','instagram','other']" :key="s" :value="s">{{orderSourceLabel(s)}}</option></select></div><div class="admin-panel"><div class="admin-table-wrap"><table class="admin-table admin-table--orders"><thead><tr><th>Order</th><th>Customer</th><th>Source</th><th>Status</th><th>Payment</th><th>Total</th><th>Created</th></tr></thead><tbody><tr v-for="o in result.items" :key="o.id" class="admin-click-row" @click="$router.push(`/admin/orders/${o.id}`)"><td><strong>#{{o.order_number}}</strong><small>{{o.items?.map(i=>`${i.title} × ${i.quantity}`).join(', ')}}</small></td><td><strong>{{o.customer_name}}</strong><small>{{o.customer_phone}}</small></td><td><span class="admin-source-badge">{{orderSourceLabel(o.source)}}</span></td><td><span class="status-badge" :data-status="o.status">{{orderStatusLabel(o.status)}}</span></td><td><span class="status-badge" :data-payment="o.payment_status">{{paymentStatusLabel(o.payment_status)}}</span></td><td><strong>{{formatMoney(o.total_minor,o.currency)}}</strong></td><td>{{formatDateTime(o.created_at)}}</td></tr><tr v-if="!loading&&!result.items.length"><td colspan="7" class="admin-empty-cell">No orders found.</td></tr></tbody></table></div><div class="admin-pagination"><button type="button" :disabled="filters.page<=1" @click="filters.page--">←</button><span>Page {{filters.page}} / {{pages()}}</span><button type="button" :disabled="filters.page>=pages()" @click="filters.page++">→</button></div></div></section></template>
